import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  pow,
  sub,
  dot,
  max,
  normalize,
  cameraPosition,
  positionWorld,
  normalWorld,
  texture,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CapsuleGeometry, PointLight, Color, Texture, DoubleSide } =
    THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'pricing-badge';

  // -----------------------------------------------------------------------
  // Capsule geometry — real extruded 3D bevel, not a flat rect.
  // -----------------------------------------------------------------------
  const radius = 0.2;
  const barrel = 0.7;
  const geometry = new CapsuleGeometry(radius, barrel, 8, 24);
  geometry.rotateZ(Math.PI / 2); // lay pill flat along X
  geometry.scale(1, 1, 0.4); // flatten depth for a badge-plate silhouette

  // Placeholder texture object — mutated in-place once the real grain map
  // finishes loading (TSL keeps a reference, not a snapshot).
  const grainTex = new Texture();
  grainTex.colorSpace = THREE.SRGBColorSpace;
  grainTex.wrapS = THREE.RepeatWrapping;
  grainTex.wrapT = THREE.RepeatWrapping;

  const inkColor = vec3(
    new Color(colors.ink).r,
    new Color(colors.ink).g,
    new Color(colors.ink).b
  );
  const accentColor = vec3(
    new Color(colors.accent).r,
    new Color(colors.accent).g,
    new Color(colors.accent).b
  );

  const grainSample = texture(grainTex, uv().mul(2.0));
  const baseColor = mix(inkColor, inkColor.mul(1.15), grainSample.r);

  // Fresnel-driven accent edge light — the ONE accent, kept small (<=10% frame).
  const viewDir = normalize(sub(cameraPosition, positionWorld));
  const fresnel = pow(sub(1.0, max(dot(viewDir, normalWorld), 0.0)), 3.0);
  const edgeGlow = accentColor.mul(fresnel).mul(float(1.6));

  const material = new MeshStandardNodeMaterial();
  material.colorNode = baseColor;
  material.emissiveNode = edgeGlow;
  material.roughness = 0.55;
  material.metalness = 0.4;
  material.side = DoubleSide;

  const badgeMesh = new Mesh(geometry, material);
  badgeMesh.name = 'pricing-badge-capsule';
  group.add(badgeMesh);

  ctx.textureLoader
    .loadTexture(config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png')
    .then((tex) => {
      grainTex.image = tex.image;
      grainTex.needsUpdate = true;
      material.needsUpdate = true;
    })
    .catch(() => {});

  // -----------------------------------------------------------------------
  // Local accent rim light — behind/above the badge, intensity <=1.5.
  // -----------------------------------------------------------------------
  const rimLight = new PointLight(new Color(colors.accent), 1.1, 2.5, 2.0);
  rimLight.position.set(-0.3, 0.15, 0.6);
  group.add(rimLight);

  // -----------------------------------------------------------------------
  // Subtle contact shadow for grounding.
  // -----------------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(1.3, 0.55);
  const { MeshBasicNodeMaterial } = { MeshBasicNodeMaterial: undefined };
  // (use standard node material with dark emissive-free color for a soft shadow disc)
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.transparent = true;
  shadowMat.opacity = 0.45;
  shadowMat.roughness = 1.0;
  shadowMat.metalness = 0.0;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.28, -0.05);
  shadowMesh.rotation.x = 0;
  group.add(shadowMesh);

  // -----------------------------------------------------------------------
  // Motion state
  // -----------------------------------------------------------------------
  const baseY = 0;
  const baseScale = 1;
  let hoverTween = null;
  let pressTween = null;

  // gentle entrance settle
  group.scale.setScalar(0.98);
  const entranceTl = gsap.timeline();
  entranceTl.to(group.scale, {
    x: baseScale,
    y: baseScale,
    z: baseScale,
    duration: 0.9,
    ease: 'power4.out',
  });

  function onHoverIn() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(badgeMesh.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
    gsap.to(rimLight, { intensity: 1.5, duration: 0.4, ease: 'power2.out' });
  }

  function onHoverOut() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(badgeMesh.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out',
    });
    gsap.to(rimLight, { intensity: 1.1, duration: 0.4, ease: 'power2.out' });
  }

  function onClick() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline();
    pressTween
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(group.scale, { x: baseScale, y: baseScale, z: baseScale, duration: 0.25, ease: 'power2.out' });
    ctx.emit('hub-pricing.select', { source: 'pricing-badge' });
  }

  group.userData.handlers = {
    pointerenter: onHoverIn,
    pointerleave: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    entranceTl.kill();
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(badgeMesh.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(rimLight);

    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    grainTex.dispose();

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) obj.material.dispose?.();
    });
  };

  return group;
}
